import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import {newBridgeState,bridgePage,bridgeAssignmentReady,collectAssignmentPdfReport,validateAssignmentPdfMeta} from '../site/marketing-bridge.js';
import {nowInRiyadh} from '../site/planner.js';
import {encodeAssignmentPdf} from '../site/assignment-pdf.js';
const date=(offset)=>{const d=new Date(nowInRiyadh()+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+offset);return d.toISOString().slice(0,10);};
const ideas=[{code:'V01',kind:'video',title:'فكرة فيديو من التصنيف الأول',marketingCategory:'بيعي - قسط'},{code:'I01',kind:'image',title:'فكرة صورة من التصنيف الثاني',marketingCategory:'بيعي - كاش'},{code:'V02',kind:'video',title:'فكرة بدون نشر وتمويل',marketingCategory:'بيعي - قسط'}].map(idea=>({...idea,reviewStatus:'معتمد',creativeApprovedAt:'2026-11-26T00:00:00Z',approvedCarMode:'none',approvedVehicles:[]}));
const bridge=newBridgeState();Object.assign(bridge,{category:'بيعي',selectedCodes:ideas.map(a=>a.code),ideaCode:'V01',mode:'none',chosenStocks:[],taskTypeId:'type',taskTypes:[{id:'type',name:'بيع'}],executors:[{user_id:'photo',department_id:'p',department_name:'قسم التصوير',full_name:'أحمد ناجي'},{user_id:'editor',department_id:'m',department_name:'المونتاج',full_name:'محمود'},{user_id:'designer',department_id:'m',department_name:'التصميم',full_name:'عبدالله'}],formats:[{id:'video',width:1080,height:1920,mediaKinds:['video']},{id:'image',width:1080,height:1080,mediaKinds:['image']}],formatIdsByIdea:{V01:['video'],I01:['image'],V02:['video']},carModesByIdea:{V01:'none',I01:'none',V02:'none'},carSelectionsByIdea:{V01:[],I01:[],V02:[]},assignmentsByIdea:{V01:[{assignee:'photo|p',dueOn:date(1)},{assignee:'editor|m',dueOn:date(3)}],I01:[{assignee:'photo|p',dueOn:''},{assignee:'designer|m',dueOn:date(4)}],V02:[{assignee:'editor|m',dueOn:date(5)}]},planDrafts:[{id:'agenda',kind:'agenda',name:'أجندة فبراير'},{id:'campaign',kind:'campaign',name:'حملة فبراير'}],placementsByIdea:{V01:{kind:'shared',agendaDraftId:'agenda',agendaDate:date(8),campaignDraftId:'campaign',campaignDate:date(9)},I01:{kind:'agenda',draftId:'agenda',date:date(10)},V02:{kind:'none'}}});
const state={bridge,plan:{assets:ideas,carousels:[]}};
assert(bridgeAssignmentReady(state));
const controls={dueOn_V01_0:{value:''},dueOn_V01_1:{value:date(6)},placementKind_V01:{value:'shared'},agendaDraft_V01:{value:'agenda'},agendaDate_V01:{value:date(11)},campaignDraft_V01:{value:'campaign'},campaignDate_V01:{value:date(12)}};
const form={elements:{namedItem:name=>controls[name]||null}};
const before=JSON.stringify(state);
const report=collectAssignmentPdfReport(state,form,{season:'عيد الفطر',seasonFrom:date(8),seasonTo:date(14),campaignEnd:date(20)});
assert.equal(JSON.stringify(state),before,'export is read-only');
assert.equal(report.title,'أجندة فبراير + حملة فبراير');assert.equal(report.groups.length,2);
assert.equal(report.groups[0].ideas.length,2);assert.equal(report.groups[1].ideas[0].rows[1].requirement,'صورة');
assert.deepEqual(report.groups[0].ideas[0].rows[0],{executor:'أحمد ناجي',requirement:'تصوير',dueOn:'',publishOn:'',fundOn:''});
assert.equal(report.groups[0].ideas[0].rows[1].dueOn,date(6));assert.equal(report.groups[0].ideas[0].rows[1].publishOn,date(11));assert.equal(report.groups[0].ideas[0].rows[1].fundOn,date(12));
assert.equal(report.groups[0].ideas[1].rows[0].publishOn,'لا يوجد');assert.equal(report.groups[0].ideas[1].rows[0].fundOn,'لا يوجد');
assert.equal(report.groups[1].ideas[0].rows[1].fundOn,'لا يوجد');
assert.equal(report.campaignEnd,date(20));assert.equal(report.season,'عيد الفطر');
assert.throws(()=>validateAssignmentPdfMeta({seasonFrom:date(10),seasonTo:date(1)}));
assert.throws(()=>validateAssignmentPdfMeta({campaignEnd:'2027-02-31'}));
assert.match(bridgePage(state),/type="button" class="btn bridge-pdf-export" data-action="bridge-export-pdf"\s*>/);
controls.dueOn_V01_1.value='';assert.throws(()=>collectAssignmentPdfReport(state,form),/تاريخ التسليم/);controls.dueOn_V01_1.value=date(6);
bridge.assignmentsByIdea.V02[0].dueOn='';assert(!bridgeAssignmentReady(state));assert.throws(()=>collectAssignmentPdfReport(state,form),/أكمل الاختيارات/);bridge.assignmentsByIdea.V02[0].dueOn=date(5);
// Rendering contract: native download without invoking assignment submission.
const app=readFileSync(new URL('../site/app.js',import.meta.url),'utf8');const block=app.slice(app.indexOf("if(control?.dataset.action==='bridge-export-pdf')"),app.indexOf("if(control?.dataset.action==='bridge-show-history-task')"));
assert(block.includes('collectAssignmentPdfReport(state,form)'));assert(block.includes('downloadAssignmentPdf(report)'));assert(!/assignBridgeIdea|submitBridgeAssignment|fetch\(/.test(block));
const pdf=encodeAssignmentPdf([{width:2,height:2,data:new Uint8Array([255,216,255,217])}]);const raw=Buffer.from(await pdf.arrayBuffer());assert.equal(raw.subarray(0,8).toString(),'%PDF-1.4');const tail=raw.toString('latin1');const xref=Number(tail.match(/startxref\n(\d+)/)[1]);assert.equal(raw.subarray(xref,xref+4).toString(),'xref');
console.log('PASS: selected ideas, grouping, live dates, shared/agenda/no destination, photography, optional Nagi date, validation, report-only metadata, no state writes, direct download and PDF xref.');
